// Turns what the calling workflow built into a Resend email (0039). Callers
// still build the same raw RFC 2822 message they used to hand to Gmail, so
// this reads To / Cc / Subject / In-Reply-To / References and the text from
// it; or they pass to / subject / text directly. Who it's from comes from the
// database: the agency's name and Elliot address (or its own domain), with
// Reply-To the agency's own address so a client's answer reaches the agency.
const input = $('When Executed by Another Workflow').first().json;
let sender = $input.first().json.sender || {};
if (typeof sender === 'string') { try { sender = JSON.parse(sender); } catch (e) { sender = {}; } }

function fromB64(s) {
  return Buffer.from(String(s || '').replace(/-/g, '+').replace(/_/g, '/').replace(/\s+/g, ''), 'base64').toString('utf8');
}
function decodeWords(v) {
  return String(v || '')
    .replace(/=\?UTF-8\?B\?([^?]*)\?=/gi, (m, b) => Buffer.from(b, 'base64').toString('utf8'))
    .replace(/=\?UTF-8\?Q\?([^?]*)\?=/gi, (m, q) => Buffer.from(q.replace(/_/g, ' ').replace(/=([0-9A-F]{2})/gi, (x, h) => String.fromCharCode(parseInt(h, 16))), 'latin1').toString('utf8'));
}
function parseRaw(rawB64) {
  const raw = fromB64(rawB64).replace(/\r\n/g, '\n');
  const cut = raw.indexOf('\n\n');
  const head = cut >= 0 ? raw.slice(0, cut) : raw;
  let body = cut >= 0 ? raw.slice(cut + 2) : '';
  const headers = {};
  head.replace(/\n[ \t]+/g, ' ').split('\n').forEach((line) => {
    const i = line.indexOf(':');
    if (i > 0) headers[line.slice(0, i).trim().toLowerCase()] = line.slice(i + 1).trim();
  });
  if (/base64/i.test(headers['content-transfer-encoding'] || '')) body = Buffer.from(body.replace(/\s+/g, ''), 'base64').toString('utf8');
  return { headers, body };
}
const list = (v) => (Array.isArray(v) ? v : String(v || '').split(','))
  .map((a) => String(a).trim()).filter((a) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.replace(/^.*<|>$/g, '')));
const quote = (name) => `"${String(name || 'Elliot').replace(/[\r\n]+/g, ' ').replace(/["\\]/g, '').trim().slice(0, 80)}"`;

const parsed = input.raw_message ? parseRaw(input.raw_message) : { headers: {}, body: '' };
const h = parsed.headers;
const to = list(input.to || h.to);
const cc = list(input.cc || h.cc);
const subject = decodeWords(input.subject || h.subject || '').trim() || '(no subject)';
const text = String(input.text || parsed.body || '').replace(/\r\n/g, '\n');
const inReplyTo = String(input.in_reply_to || h['in-reply-to'] || '').trim();
const references = String(input.references || h.references || inReplyTo).trim();
const address = String(sender.address || 'notifications@mail.getelliot.eu');

const email = {
  from: `${quote(sender.name)} <${address}>`,
  to,
  subject,
  text,
};
if (cc.length) email.cc = cc;
if (sender.reply_to) email.reply_to = [String(sender.reply_to)];
const headers = {};
if (inReplyTo) headers['In-Reply-To'] = inReplyTo;
if (references) headers['References'] = references;
if (Object.keys(headers).length) email.headers = headers;

// The same email for Gmail, used only if Resend fails on an email for the
// agency's own team (never for clients: they'd get it from the wrong address).
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const gmailRaw = Buffer.from([
  `To: ${to.join(', ')}`,
  cc.length ? `Cc: ${cc.join(', ')}` : null,
  `Subject: =?UTF-8?B?${b64(subject)}?=`,
  inReplyTo ? `In-Reply-To: ${inReplyTo}` : null,
  references ? `References: ${references}` : null,
  'MIME-Version: 1.0', 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64',
].filter(Boolean).join('\r\n') + '\r\n\r\n' + b64(text)).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// 0048: Resend sends an email with the same Idempotency-Key only once (for 24
// hours). 'Send via Resend' retries when the connection drops, and without a
// key a retry after Resend had already accepted the email sent it twice.
// A caller can pass its own idempotency_key (one per thing it is sending).
function hash(s) { let h1 = 5381, h2 = 52711; for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = (h1 * 33) ^ ch; h2 = (h2 * 33) ^ ch; } return (h1 >>> 0).toString(36) + (h2 >>> 0).toString(36); }
let executionId = '';
try { executionId = String($execution.id || ''); } catch (e) { executionId = ''; }
const ownKey = String(input.idempotency_key || '').trim().replace(/[^\w.:-]/g, '-').slice(0, 200);
const idempotencyKey = ownKey || `elliot-${executionId || 'x'}-${hash(JSON.stringify([email.to, email.cc || [], subject, text, inReplyTo]))}`;

return [{ json: {
  idempotency_key: idempotencyKey,
  ok_to_send: to.length > 0,
  audience: input.audience === 'team' ? 'team' : 'client',
  tenant_id: input.tenant_id || null,
  email,
  gmail_raw: gmailRaw,
} }];

// What goes back to the calling workflow, in one shape whichever way it went:
// { ok, statusCode, id, error, body: { id, error }, provider }. Callers read
// statusCode + body (like an HTTP response) or id + error.
const built = $('Build Resend Email').first().json;
const read = (name) => { try { return $(name).first().json; } catch (e) { return null; } };
const resend = read('Send via Resend');
const gmail = read('Send via Gmail (team fallback)');
function outcome(r, provider) {
  if (!r) return null;
  const status = Number(r.statusCode || 0);
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* not JSON */ } }
  const ok = status >= 200 && status < 300 && !!(body && body.id);
  const message = ok ? null : (body && (body.message || (body.error && body.error.message)))
    || (r.error && (r.error.message || String(r.error))) || `HTTP ${status || 'no response'}`;
  return { ok, status, id: ok ? body.id : null, message: message ? `${provider}: ${String(message).slice(0, 300)}` : null, provider };
}
let res;
if (!built.ok_to_send) res = { ok: false, status: 0, id: null, message: 'no valid recipient', provider: 'none' };
else {
  const a = outcome(resend, 'Resend');
  const b = outcome(gmail, 'Gmail');
  res = b ? { ...b, message: b.ok ? null : `${a && a.message}; ${b.message}` } : a;
}
const error = res.ok ? null : { message: res.message };
return [{ json: {
  ok: res.ok,
  statusCode: res.ok ? 200 : (res.status || 502),
  id: res.id,
  error,
  body: res.ok ? { id: res.id } : { error },
  provider: res.provider,
  from: built.email.from,
  to: built.email.to,
} }];
